from __future__ import annotations

import click

from .models import Note, generate_id
from .search import search as do_search
import sys
import re
from .storage import get_notes, add_note, delete_note


def _validate_non_empty(ctx, param, value):
    if not value or not value.strip():
        raise click.BadParameter(f"{param.name.capitalize()} cannot be empty.")
    return value


@click.group()
def cli():
    """Simple note‑taking CLI."""
    pass


@cli.command()
@click.option("--title", required=True, help="Note title.", callback=_validate_non_empty)
@click.option("--body", required=True, help="Note body text.", callback=_validate_non_empty)
@click.option(
    "--tags",
    default="",
    help="Comma‑separated list of tags (e.g. 'python,cli').",
)
def add(title: str, body: str, tags: str) -> None:
    """Create a new note."""
    parsed_tags = [t.strip() for t in tags.split(",") if t.strip()] if tags else []
    for tag in parsed_tags:
        if len(tag) > 100:
            click.echo(f"Error: Tag '{tag}' exceeds maximum length of 100 characters.")
            sys.exit(1)
        if not re.match(r'^[a-zA-Z0-9_-]+$', tag):
            click.echo(f"Error: Tag '{tag}' contains invalid characters. Only letters, digits, hyphens, and underscores are allowed.")
            sys.exit(1)
    note = Note(id=generate_id(), title=title, body=body, tags=parsed_tags)
    add_note(note)
    click.echo(f"Added note {note.id}")


@cli.command(name="list")
@click.option(
    "--tags",
    default="",
    help="Comma‑separated list of tags to filter by.",
)
def cmd_list(tags: str) -> None:
    """List all notes."""
    parsed_tags = [t.strip() for t in tags.split(",") if t.strip()] if tags else None
    results = do_search(get_notes(), query="", tags=parsed_tags)
    if not results:
        click.echo("No notes found.")
        return
    for n in results:
        tag_str = ", ".join(n.tags) if n.tags else "(none)"
        click.echo(f"[{n.id}] {n.title}  tags: {tag_str}")


@cli.command()
@click.option("--query", required=True, help="Search query (substring).")
@click.option(
    "--tags",
    default="",
    help="Comma‑separated list of tags to filter by.",
)
def search(query: str, tags: str) -> None:
    """Search notes by query and/or tags."""

    parsed_tags = [t.strip() for t in tags.split(",") if t.strip()] if tags else None
    results = do_search(get_notes(), query=query, tags=parsed_tags)
    if not results:
        click.echo("No matching notes.")
        return
    for n in results:
        tag_str = ", ".join(n.tags) if n.tags else "(none)"
        click.echo(f"[{n.id}] {n.title}  tags: {tag_str}")


@cli.command()
@click.argument("note_id")
def delete(note_id: str) -> None:
    """Delete a note by its id."""
    if delete_note(note_id):
        click.echo(f"Deleted note {note_id}")
    else:
        click.echo(f"Note {note_id} not found.")


def main() -> None:
    cli()

from __future__ import annotations

import uuid
from dataclasses import dataclass, field


@dataclass(frozen=True)
class Note:
    """Immutable note with id, title, body and optional tags."""

    id: str
    title: str
    body: str
    tags: list[str] = field(default_factory=list)

    def search_text(self) -> str:
        """Return a combined searchable string (title + body)."""
        return f"{self.title} {self.body}"

    def to_dict(self) -> dict:
        return {"id": self.id, "title": self.title, "body": self.body, "tags": self.tags}

    @classmethod
    def from_dict(cls, d: dict) -> Note:
        return cls(
            id=d["id"],
            title=d["title"],
            body=d["body"],
            tags=d.get("tags", []),
        )


def generate_id() -> str:
    return uuid.uuid4().hex[:8]

"""File-based JSON storage for notes."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Dict, List

from .models import Note

DEFAULT_PATH: Path = Path(__file__).resolve().parents[2] / "out.json"
# Backward-compatible alias
STORAGE_PATH: Path = DEFAULT_PATH


def _read_store(path: Path = DEFAULT_PATH) -> Dict[str, Any]:
    """Read the store from *path*.

    Returns ``{"notes": []}`` if the file is missing; raises on invalid JSON.
    """
    if not path.exists():
        return {"notes": []}
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError, UnicodeDecodeError):
        return {"notes": []}
    if not isinstance(raw, dict):
        return {"notes": []}
    notes = raw.get("notes")
    if not isinstance(notes, list):
        return {"notes": []}
    return raw


def _write_store(path: Path, store: Dict[str, Any]) -> None:
    """Write *store* to *path* as JSON."""
    path.write_text(json.dumps(store, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def get_notes(path: Path = DEFAULT_PATH) -> List[Note]:
    """Return all notes from the store at *path*."""
    raw = _read_store(path)
    return [Note.from_dict(d) for d in raw.get("notes", [])]


def add_note(note: Note, path: Path = DEFAULT_PATH) -> None:
    """Append *note* to the store at *path*."""
    raw = _read_store(path)
    raw.setdefault("notes", []).append(note.to_dict())
    _write_store(path, raw)


def delete_note(note_id: str, path: Path = DEFAULT_PATH) -> bool:
    """Remove the note with *note_id* from the store.

    Returns ``True`` iff a matching note was found and removed.
    """
    raw = _read_store(path)
    notes: List[Dict[str, Any]] = raw.get("notes", [])
    before_len = len(notes)
    notes[:] = [d for d in notes if d.get("id") != note_id]
    raw["notes"] = notes
    if len(notes) < before_len:
        _write_store(path, raw)
        return True
    return False


def clear_all(path: Path = DEFAULT_PATH) -> None:
    """Wipe all notes and write a fresh empty store."""
    _write_store(path, {"notes": []})

